import itertools

def impl(p,q):
    return (not p) or q

def eval_formula(num, A, B):
    if num==1:
        return (not (A and B)) == ((not A) or (not B))
    if num==2:
        return (not (A or B)) == ((not A) and (not B))
    if num==3:
        return (impl(A,B)) == (impl(not B, not A))
    if num==4:
        return (impl(A,B)) == ((not A) or B)
    if num==5:
        return (impl(not A, B)) == (A or (not B))
    if num==6:
        return (not impl(A,B)) == (A and (not B))

for num in range(1,7):
    results = [eval_formula(num,A,B) for A in [False,True] for B in [False,True]]
